import { useState, useCallback, use } from 'react';
import { ReactFlow, applyNodeChanges, applyEdgeChanges, addEdge, NodeChange, EdgeChange, Edge, Node, MiniMap, Controls, Background } from '@xyflow/react';
import '@xyflow/react/dist/style.css';
import { StoryState, useGameState } from '../stores/StoryStore';
import styled from 'styled-components';


const GraphContainer = styled.div`
  width: 100%;
  height: 100%;
  border: 1px solid #eee;
  background: #f9f9f9;

  /* Custom styling for the nodes to make them circles */
  .react-flow__node {
    border-radius: 50%;
    width: 50px;
    height: 50px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 10px;
  }
`;

export function StoryBoard() {
    const graph = useGameState((state) => state.displayGraph);


    const onNodeClick = useCallback((event: React.MouseEvent, node: Node) => {
        useGameState.getState().setCurrentNodeId({ kind: 'node', id: node.id });
    }, []);

    const onEdgeClick = useCallback((event: React.MouseEvent, edge: Edge) => {
        useGameState.getState().setCurrentNodeId({ kind: 'transition', id: edge.id });
    }, []);

    const onConnect = useCallback((params: Edge | any) => {
        useGameState.getState().addTransition(params.source, params.target);
    }, []);

    const onNodesChange = useCallback((changes: NodeChange[]) => {
        for (const change of changes) {
            if (change.type === 'position' && change.position) {
                useGameState.getState().setNodeAttributes(change.id, { position: change.position });
            }
        }
    }, []);

    return <GraphContainer>
        <ReactFlow
            nodes={graph.nodes}
            edges={graph.edges}
            onNodeClick={onNodeClick}
            onEdgeClick={onEdgeClick}
            onNodesChange={onNodesChange}
            onConnect={onConnect}
            fitView
        >
            <Controls />
            <Background />

        </ReactFlow>
    </GraphContainer>
}